#!/usr/bin/env bash
#
# Generates:
#
#   networkFiles/genesis.json
#   networkFiles/keys/<validator>/key
#   ./accounts/accounts.json
#
# The network contains:
#   - 24 QBFT validators generated by Besu
#   - 2000 funded client accounts generated locally
#
# Client accounts are NOT validators.
# They are simply funded Ethereum accounts used by the workload generator.
#

set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"

PYTHON="${ROOT_DIR}/venv/bin/python"

BESU_IMAGE="hyperledger/besu:24.7.0"

CONFIG_FILE="${ROOT_DIR}/config/qbftConfigFile.json"
NETWORK_DIR="${ROOT_DIR}/networkFiles"
GENESIS_FILE="${NETWORK_DIR}/genesis.json"

# Number of funded workload/client accounts.
NUM_ACCOUNTS="${NUM_ACCOUNTS:-2000}"

# Balance per client account.
#
# 1 ETH = 10^18 wei.
# 1000 ETH is intentionally generous for benchmarking.
ACCOUNT_BALANCE="${ACCOUNT_BALANCE:-1000000000000000000000}"


echo "=========================================="
echo "Generating QBFT test network"
echo "=========================================="
echo
echo "Validators : 15"
echo "Client accounts : ${NUM_ACCOUNTS}"
echo "Balance/account : ${ACCOUNT_BALANCE} wei"
echo


# ------------------------------------------------------------
# 1. Clean previous network
# ------------------------------------------------------------

echo "[1/5] Cleaning previous network files..."

rm -rf "${NETWORK_DIR}"

mkdir -p "${NETWORK_DIR}"
mkdir -p "${ROOT_DIR}/accounts"


# ------------------------------------------------------------
# 2. Generate QBFT validators + genesis
# ------------------------------------------------------------

echo "[2/5] Generating QBFT validators and genesis..."

docker run --rm \
  --user "$(id -u):$(id -g)" \
  -v "${ROOT_DIR}/config:/config:ro" \
  -v "${NETWORK_DIR}:/networkFiles" \
  "${BESU_IMAGE}" \
  operator generate-blockchain-config \
    --config-file=/config/qbftConfigFile.json \
    --to=/networkFiles \
    --private-key-file-name=key


# ------------------------------------------------------------
# 3. Generate rich client accounts
# ------------------------------------------------------------

echo "[3/5] Generating ${NUM_ACCOUNTS} funded client accounts..."

"${PYTHON}" \
  "${ROOT_DIR}/scripts/00-generate_accounts.py" \
  "${NUM_ACCOUNTS}" \
  "${ACCOUNT_BALANCE}" \
  "${ROOT_DIR}/accounts/accounts.json"


# ------------------------------------------------------------
# 4. Merge all funded accounts into genesis
# ------------------------------------------------------------

echo "[4/5] Updating genesis alloc..."

"${PYTHON}" - "${CONFIG_FILE}" "${GENESIS_FILE}" \
         "${ROOT_DIR}/accounts/accounts.json" <<'PY'

from curses import echo
import json
import sys
from pathlib import Path


config_path = Path(sys.argv[1])
genesis_path = Path(sys.argv[2])
accounts_path = Path(sys.argv[3])


# ------------------------------------------------------------
# Load generated genesis
# ------------------------------------------------------------

with genesis_path.open() as f:
    genesis = json.load(f)


# ------------------------------------------------------------
# Load original QBFT configuration
# ------------------------------------------------------------

with config_path.open() as f:
    config = json.load(f)


# ------------------------------------------------------------
# Existing alloc from qbftConfigFile.json
# ------------------------------------------------------------

config_alloc = (
    config
    .get("genesis", {})
    .get("alloc", {})
)


genesis.setdefault("alloc", {})


# ------------------------------------------------------------
# Preserve accounts already specified in config
# ------------------------------------------------------------

print(
    f"Existing configured alloc accounts: "
    f"{len(config_alloc)}"
)

for address, account in config_alloc.items():

    address = address.lower()

    genesis["alloc"][address] = account


# ------------------------------------------------------------
# Load generated workload accounts
# ------------------------------------------------------------

with accounts_path.open() as f:
    accounts = json.load(f)


print(
    f"Generated workload accounts: "
    f"{len(accounts)}"
)


# ------------------------------------------------------------
# Add workload accounts
# ------------------------------------------------------------

for account in accounts:

    address = account["address"].lower()
    balance = account["balance"]

    genesis["alloc"][address] = {
        "balance": balance
    }


# ------------------------------------------------------------
# Write final genesis
# ------------------------------------------------------------

with genesis_path.open("w") as f:

    json.dump(
        genesis,
        f,
        indent=2
    )

    f.write("\n")


print()
print(
    f"Final genesis alloc contains "
    f"{len(genesis['alloc'])} accounts."
)

PY


# ------------------------------------------------------------
# 5. Permissions and verification
# ------------------------------------------------------------

echo "[5/5] Verifying generated network..."

chmod 777 "${ROOT_DIR}/accounts"
chmod 777 "${ROOT_DIR}/accounts/accounts.json"


echo
echo "=========================================="
echo "QBFT network generation complete"
echo "=========================================="

echo
echo "Genesis:"
echo "  ${GENESIS_FILE}"

echo
echo "Validators:"
echo "  ${NETWORK_DIR}/keys/"

echo
echo "Client accounts:"
echo "  ${ROOT_DIR}/accounts/accounts.json"

echo
echo "Validator count:"

find "${NETWORK_DIR}/keys" \
    -mindepth 1 \
    -maxdepth 1 \
    -type d \
    | wc -l


echo
echo "Client account count:"

python3 - "${ROOT_DIR}/accounts/accounts.json" <<'PY'
import json
import sys

with open(sys.argv[1]) as f:
    accounts = json.load(f)

print(len(accounts))
PY


echo
echo "Genesis alloc count:"

python3 - "${GENESIS_FILE}" <<'PY'
import json
import sys

with open(sys.argv[1]) as f:
    genesis = json.load(f)

print(len(genesis.get("alloc", {})))
PY


echo
echo "First 10 client accounts:"

python3 - "${ROOT_DIR}/accounts/accounts.json" <<'PY'
import json
import sys

with open(sys.argv[1]) as f:
    accounts = json.load(f)

for i, account in enumerate(accounts[:10]):
    print(
        f"{i:03d} "
        f"{account['address']} "
        f"balance={account['balance']}"
    )
PY


echo
echo "=========================================="
echo "IMPORTANT"
echo "=========================================="
echo
echo "Client private keys are stored in:"
echo "  ${ROOT_DIR}/accounts/accounts.json"
echo
echo "Do NOT commit this file to Git."
echo
